 * transfer between holders, validation rules, and unset operations.
 */
class UserConsentedScopesDecisionAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getDecisionAt returns null on a freshly created holder.
     */
    public function testDecisionAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesDecisionAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isDecisionAtAssigned());
        $this->assertNull($holder->getDecisionAt());
    }
}
